from src.nodes.base import BaseNode
from src.runtime.assets.semantic import (
    get_asset_catalog, get_semantic_asset_enricher,
    get_asset_catalog_review,
)

class Hou_Mcp_Asset_Catalog(BaseNode):
    name = "hou_mcp_asset_catalog"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("action",     "string", widget_type="text", default="search")
        self.add_input("asset_id",   "string", widget_type="text")
        self.add_input("asset_data", "any")
        self.add_input("query",      "string", widget_type="text")
        self.add_input("environment","string", widget_type="text")
        self.add_input("role",       "string", widget_type="text")
        self.add_input("limit",      "int",    widget_type="int", default=20)
        self.add_output("result",  "any")
        self.add_output("assets",  "list")
        self.add_output("ok",      "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        action     = str(inputs.get("action") or "search").strip().lower()
        asset_id   = str(inputs.get("asset_id") or "").strip()
        asset_data = inputs.get("asset_data") or {}
        query      = str(inputs.get("query") or "").strip()
        environment= str(inputs.get("environment") or "").strip()
        role       = str(inputs.get("role") or "").strip()
        limit      = int(inputs.get("limit") or 20)
        try:
            catalog = get_asset_catalog()
            if action == "register":
                enriched = get_semantic_asset_enricher().enrich_asset(asset_data if isinstance(asset_data, dict) else {})
                entry = catalog.register_asset(asset_id or str((asset_data or {}).get("asset_id","")), enriched.to_dict(), asset_data if isinstance(asset_data, dict) else {})
                return {"result": entry.to_dict(), "assets": [], "ok": bool(entry.asset_id), "exec_out": True}
            elif action == "update":
                ok = catalog.update_asset(asset_id, asset_data if isinstance(asset_data, dict) else {})
                return {"result": {"updated": ok}, "assets": [], "ok": ok, "exec_out": True}
            elif action == "remove":
                ok = catalog.remove_asset(asset_id)
                return {"result": {"removed": ok}, "assets": [], "ok": ok, "exec_out": True}
            elif action == "get":
                entry = catalog.get_asset(asset_id)
                return {"result": entry.to_dict() if entry else {}, "assets": [], "ok": entry is not None, "exec_out": True}
            elif action == "exists":
                ok = catalog.asset_exists(asset_id)
                return {"result": {"exists": ok}, "assets": [], "ok": ok, "exec_out": True}
            elif action == "stats":
                stats = catalog.get_statistics()
                return {"result": stats, "assets": [], "ok": True, "exec_out": True}
            elif action == "review":
                rev = get_asset_catalog_review().review_catalog()
                return {"result": rev.to_dict(), "assets": [], "ok": rev.ok, "exec_out": True}
            else:  # search
                entries = catalog.search_assets(query=query, environment=environment, role=role, limit=limit)
                return {"result": {"count": len(entries)}, "assets": [e.to_dict() for e in entries], "ok": True, "exec_out": True}
        except Exception as e:
            self.log_error(f"hou_mcp_asset_catalog failed: {e}")
            return {"result": {}, "assets": [], "ok": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Asset_Catalog
